async function identity(req, db, env) {
  const signedIn = await sessionUser(req, env);
  if (signedIn) return signedIn;
  if (env.AUTH_MODE === "google" || env.LOCAL_DEV_OWNER !== "true")
    fail3(401, "Sign in to access your campus.");
  const uid2 = req.headers.get("oai-authenticated-user-id"), email = req.headers.get("oai-authenticated-user-email")?.toLowerCase();
  if (!uid2 || !email) fail3(401, "Sign in to access your campus.");
  await run3(
    db,
    "INSERT OR IGNORE INTO settings (key,value) VALUES ('owner',?)",
    uid2
  );
  const owner = await one3(db, "SELECT value FROM settings WHERE key='owner'");
  let name = req.headers.get("oai-authenticated-user-full-name") || email.split("@")[0];
  if (req.headers.get("oai-authenticated-user-full-name-encoding") === "percent-encoded-utf-8") {
    try {
      name = decodeURIComponent(name);
    } catch {
    }
  }
  await run3(
    db,
    "INSERT OR IGNORE INTO users (id,email,name,role,created) VALUES (?,?,?,?,?)",
    uid2,
    email,
    name,
    owner.value === uid2 ? "admin" : "student",
    now3()
  );
  let u = await one3(db, "SELECT * FROM users WHERE id=?", uid2) || await one3(db, "SELECT * FROM users WHERE email=?", email);
  const resolvedId = u.id;
  const invites = await rows2(
    db,
    "SELECT * FROM invitations WHERE email=?",
    email
  );
  for (const invite of invites) {
    await run3(
      db,
      "INSERT OR IGNORE INTO enrollments (id,user_id,batch_id,fee,created) VALUES (?,?,?,?,?)",
      id(),
      resolvedId,
      invite.batch_id,
      invite.fee,
      now3()
    );
    if (invite.role === "admin")
      await run3(db, "UPDATE users SET role='admin' WHERE id=?", resolvedId);
    else if (invite.role === "trainer" && u.role !== "admin")
      await run3(db, "UPDATE users SET role='trainer' WHERE id=?", resolvedId);
  }
  u = await one3(db, "SELECT * FROM users WHERE id=?", resolvedId);
  if (!u || !u.active) fail3(403, "Your account is disabled.");
  return u;
}
async function api(req, env) {
  try {
    return await handle(req, env);
  } catch (e) {
    if (e instanceof SyntaxError)
      e = new HttpError(400, "Invalid request data.");
    if (!e.status) console.error(e);
    return json2(
      {
        error: e.status ? e.message : "The request could not be completed. Please try again."
      },
      e.status || 500
    );
  }
}
